"""Seating charts: students sorted by last name and split into rows."""

import typing

import rosterkit.models


# ---
def seating_rows(
    students: typing.Iterable[rosterkit.models.Student], seats_per_row: int
) -> typing.List[str]:
    """One text line per row, students sorted by last name then first name."""
    if seats_per_row <= 0:
        raise ValueError(f"seats per row must be positive: {seats_per_row}")
    ordered = sorted(students, key=sort_key)
    if not ordered:
        raise ValueError("no students to seat")
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = []
        for student in ordered[start : start + seats_per_row]:
            names.append(student.display_name)
        row_number = start // seats_per_row + 1
        lines.append(f"Row {row_number}: " + " | ".join(names))
    return lines


def sort_key(student: rosterkit.models.Student) -> typing.Tuple[str, str]:
    return (student.last_name.casefold(), student.first_name.casefold())
