cat > tests/test_seating.py <<'EOF'
import unittest

import rosterkit.models
import rosterkit.seating


def make_student(number, last, first):
    return rosterkit.models.Student(str(number), last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student(1, "Halloway", "Juno"),
            make_student(2, "Dunmere", "Piet"),
            make_student(3, "Thistle", "Bram"),
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            rosterkit.seating.seating_rows(self.students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Thistle, Bram"]
        )

    def test_single_long_row(self):
        rows = rosterkit.seating.seating_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_same_last_name_orders_by_first_name(self):
        pair = [make_student(1, "Lee", "Zed"), make_student(2, "Lee", "Amy")]
        self.assertEqual(
            rosterkit.seating.seating_rows(pair, 2), ["Row 1: Lee, Amy | Lee, Zed"]
        )

    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows(self.students, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows(self.students, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows([], 3)
